const a=t=>{if(!t)return"Not provided";const r=new Date(t);if(isNaN(r.getTime()))return"Invalid Date";const e={day:"2-digit",month:"short",year:"2-digit"};return new Intl.DateTimeFormat("en-GB",e).format(r).replace(/ /g,"-")},s=t=>{if(!t)return"-";if(typeof t=="string"&&/^\d{1,2}:\d{1,2}(:\d{1,2})?$/.test(t)){const[e,o]=t.split(":").map(Number),n=e>=12?"PM":"AM";return`${e%12||12}:${o.toString().padStart(2,"0")} ${n}`}const r=new Date(t);return isNaN(r.getTime())?"-":r.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit",hour12:!0})};export{s as a,a as f};
